import {defaults,examples,calculate,health,setup,operating,irr} from './model.js';
const $=q=>document.querySelector(q),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0,notation:Math.abs(v)>=1000000?'compact':'standard'}).format(v),short=v=>Math.abs(v)>=1000000?'$'+(v/1000000).toFixed(2)+'M':'$'+Math.round(v/1000)+'K',pct=v=>v===null?'N/A':(v*100).toFixed(1)+'%',pb=v=>v===null?'Beyond horizon':v.toFixed(1)+' mo';
const colors=['#4265df','#48a88d','#9b81d9','#dda556','#688ca8'],icons=['◉','✧','▤','⌁','⚙'];
let state={projects:structuredClone(examples),settings:{...defaults},excluded:[],view:'overview',scenario:'base'},storageOK=true,selected=null,query='';
try{const saved=JSON.parse(localStorage.getItem('ai-capital-v1'));if(saved&&Array.isArray(saved.projects)&&saved.projects.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&Object.keys(examples[0]).every(k=>typeof p[k]===typeof examples[0][k]))&&saved.settings&&Object.keys(defaults).every(k=>typeof saved.settings[k]===typeof defaults[k])&&[2,3,5,10].includes(saved.settings.years)&&saved.settings.rate>=0&&saved.settings.rate<=80){state={...state,...saved};state.view='overview';}}catch{storageOK=false;}
function save(){try{localStorage.setItem('ai-capital-v1',JSON.stringify(state));}catch{storageOK=false;}$('#saved').textContent=storageOK?'● Saved on this browser':'● Changes kept for this session';}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600);}
function results(s=state.settings){return state.projects.map((p,i)=>({p,i,r:calculate(p,s)}));}
function portfolio(s=state.settings){const all=results(s).filter(x=>!state.excluded.includes(x.p.id));const flows=Array(s.years*12+1).fill(0);all.forEach(x=>x.r.flows.forEach((v,i)=>flows[i]+=v));let c=flows[0],payback=null;for(let m=1;m<flows.length;m++){if(payback===null&&c<0&&c+flows[m]>=0)payback=m-1-c/flows[m];c+=flows[m];}return {all,npv:all.reduce((v,x)=>v+x.r.npv,0),cap:all.reduce((v,x)=>v+x.r.cap,0),benefit:all.reduce((v,x)=>v+x.r.totalBenefits,0),cost:all.reduce((v,x)=>v+x.r.totalCosts,0),irr:irr(flows),payback,flows};}
const badge=(value,cls)=>`<span class="badge ${cls}">${esc(value)}</span>`;
const recBadge=v=>badge(v,v==='Scale'?'green':v==='Continue'?'blue':v==='Intervene'?'amber':'red');
function metrics(){const a=portfolio(),roi=a.cost?(a.benefit-a.cost)/a.cost:0;return `<div class="metrics"><div class="metric"><div class="metric-top">Portfolio NPV <span class="metric-icon">↗</span></div><strong>${short(a.npv)}</strong><small class="${a.npv>0?'green':''}">${state.settings.years}-year value at ${state.settings.rate}% hurdle rate</small></div><div class="metric"><div class="metric-top">Initial capital <span class="metric-icon">▣</span></div><strong>${short(a.cap)}</strong><small>Build, data readiness, and training</small></div><div class="metric"><div class="metric-top">Portfolio IRR <span class="metric-icon">⌁</span></div><strong>${pct(a.irr)}</strong><small>Annualized from monthly cash flows</small></div><div class="metric"><div class="metric-top">Portfolio payback <span class="metric-icon">◷</span></div><strong>${a.payback===null?'—':a.payback.toFixed(1)+' mo'}</strong><small>${a.payback===null?'Not reached in selected horizon':pct(roi)+' ROI · total cost basis'}</small></div></div>`;}
function cashChart(){const a=portfolio();let cumulative=a.flows[0],pts=[cumulative];for(let y=1;y<=state.settings.years;y++){cumulative+=a.flows.slice((y-1)*12+1,y*12+1).reduce((v,f)=>v+f,0);pts.push(cumulative);}const min=Math.min(...pts,0),max=Math.max(...pts,1),xx=i=>57+i*(490/state.settings.years),yy=v=>185-(v-min)/(max-min)*155;const path=pts.map((v,i)=>`${i?'L':'M'}${xx(i)},${yy(v)}`).join(' ');return `<svg class="chart" viewBox="0 0 580 218" role="img" aria-label="Cumulative undiscounted portfolio cash flow"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4265df" stop-opacity=".13"/><stop offset="1" stop-color="#4265df" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{const v=min+(max-min)*i/3;return `<line x1="57" y1="${yy(v)}" x2="547" y2="${yy(v)}" stroke="#eef1f6"/><text x="3" y="${yy(v)+3}">${short(v)}</text>`;}).join('')}<line x1="57" x2="547" y1="${yy(0)}" y2="${yy(0)}" stroke="#bec9e1" stroke-dasharray="4 4"/><path d="${path} L547,185 L57,185Z" fill="url(#area)"/><path d="${path}" fill="none" stroke="#4265df" stroke-width="2.5"/>${pts.map((v,i)=>`<circle cx="${xx(i)}" cy="${yy(v)}" r="3" fill="#fff" stroke="#4265df" stroke-width="2"><title>Year ${i}: ${money(v)}</title></circle><text x="${xx(i)}" y="209" text-anchor="middle">${i?'Year '+i:'Start'}</text>`).join('')}</svg>`;}
function allocationChart(){const a=portfolio().all,max=Math.max(...a.map(x=>x.r.cap),1);return `<svg class="chart" viewBox="0 0 430 218" role="img" aria-label="NPV compared with initial capital by project">${[0,1,2,3].map(i=>`<line x1="40" x2="413" y1="${30+i*50}" y2="${30+i*50}" stroke="#eef1f6"/>`).join('')}${a.map(x=>{const r=x.r,v=Math.max(-1,Math.min(4,r.npv/Math.max(r.cap,1))),cx=48+(r.cap/max)*335,cy=170-(v+1)*28;return `<circle cx="${cx}" cy="${cy}" r="${8+x.p.adoption/12}" fill="${colors[x.i%5]}" opacity=".8"><title>${esc(x.p.name)}: ${money(r.npv)} NPV, ${money(r.cap)} capital, ${x.p.adoption}% adoption</title></circle><text x="${cx}" y="${cy+4}" text-anchor="middle" style="fill:white;font-weight:600">${x.i+1}</text>`;}).join('')}<text x="215" y="212" text-anchor="middle">Initial capital →</text><text transform="translate(14 115) rotate(-90)" text-anchor="middle">NPV / capital →</text></svg>`;}
function table(){const all=results().filter(x=>`${x.p.name} ${x.p.team}`.toLowerCase().includes(query.toLowerCase()));return `<div class="panel table-panel"><div class="table-head"><div><h2>Investment portfolio <span class="pill">${state.projects.length} automations</span></h2><p>Compare returns. Open an automation to change its business case.</p></div><input id="search" aria-label="Search automations" placeholder="⌕  Search automations" value="${esc(query)}"></div><div class="table-wrap"><table><thead><tr><th>INCLUDE / AUTOMATION</th><th>STAGE</th><th>INITIAL CAPITAL</th><th>NPV</th><th>IRR</th><th>PAYBACK</th><th>EVIDENCE</th><th>DECISION</th></tr></thead><tbody>${all.map(({p,i,r})=>`<tr><td><div class="project-cell"><input type="checkbox" data-include="${esc(p.id)}" aria-label="Include ${esc(p.name)} in portfolio" ${state.excluded.includes(p.id)?'':'checked'}><span class="project-icon" style="background:${colors[i%5]}13;color:${colors[i%5]}">${icons[i%5]}</span><button class="name-button" data-project="${esc(p.id)}"><strong>${esc(p.name)}</strong><small>${esc(p.team)} · ${esc(p.owner)}</small></button></div></td><td>${badge(p.stage,p.stage==='Production'?'green':'blue')}</td><td>${short(r.cap)}</td><td><strong style="color:${r.npv>0?'var(--green)':'var(--red)'}">${short(r.npv)}</strong></td><td>${pct(r.irr)}</td><td>${pb(r.payback)}</td><td>${badge(p.baseline,p.baseline==='Verified'?'green':'amber')}</td><td>${recBadge(r.recommendation)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No automations match your search.</td></tr>'}</tbody></table></div><div class="table-foot"><span>${portfolio().all.length} included in portfolio · ${state.settings.capacity?'Cash + capacity value':'Cash benefit case'}</span><span>Live calculations · Click a project to inspect assumptions →</span></div></div>`;}
function overview(){const risk=results().filter(x=>x.r.recommendation==='Intervene'),best=[...portfolio().all].sort((a,b)=>b.r.npv-a.r.npv)[0];return metrics()+`<div class="charts"><div class="panel"><div class="panel-head"><div><h2>From investment to value</h2><p>Cumulative net cash flow across the selected portfolio</p></div><span class="pill">${state.settings.years}-year outlook</span></div>${cashChart()}<div class="legend"><span><i style="background:var(--blue)"></i>Portfolio cash flow</span><span>Includes recurring AI operating costs</span></div></div><div class="panel"><div class="panel-head"><div><h2>The capital allocation lens</h2><p>Higher value per dollar invested · Bubble size = adoption</p></div></div>${allocationChart()}<div class="legend">${portfolio().all.map(x=>`<span><i style="background:${colors[x.i%5]}"></i>${x.i+1}. ${esc(x.p.name.split(' ').slice(0,2).join(' '))}</span>`).join('')}</div></div></div>`+table()+`<div class="insight"><b>✧</b><p><strong>Decision brief.</strong> ${best?`${esc(best.p.name)} has the highest modeled NPV at ${short(best.r.npv)}.`:'Select an automation to form a portfolio.'} ${risk.length} initiative${risk.length===1?'':'s'} need evidence or health intervention before additional capital is committed. Recommendations are rule based and require executive review.</p></div>`;}
function scenarios(){const a=portfolio(),benefits=[60,80,100,120,140],costs=[80,90,100,110,120];return metrics()+`<div class="scenario-grid"><div class="panel"><h2>Move the assumptions</h2><p style="font-size:11px">Every change recalculates the portfolio immediately.</p>${[['benefitFactor','Benefit realization',40,160,1,'%'],['costFactor','Cost multiplier',60,180,1,'%'],['delay','Additional rollout delay',0,24,1,' months']].map(([key,label,min,max,step,suffix])=>`<div class="slider-field"><label for="${key}">${label}<b id="${key}-value">${state.settings[key]}${suffix}</b></label><input id="${key}" data-setting="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${state.settings[key]}"></div>`).join('')}<label class="switch"><input id="capacity" type="checkbox" ${state.settings.capacity?'checked':''}> Include recovered capacity value</label><p class="detail-note">Capacity value is hours × loaded hourly cost × realization. It is an economic proxy. Validate redeployment and keep it separate from direct savings.</p><p style="font-size:10px">Current scenario: ${esc(state.scenario)}. Adoption and project ramp still apply after the portfolio multiplier.</p></div><div class="panel"><div class="panel-head"><div><h2>How resilient is your investment?</h2><p>Two-variable sensitivity · portfolio NPV</p></div><span class="pill">${state.settings.rate}% discount</span></div><div class="table-wrap"><table class="heat"><thead><tr><th>Benefits ↓ / Costs →</th>${costs.map(c=>`<th>${c}%</th>`).join('')}</tr></thead><tbody>${benefits.map(b=>`<tr><th>${b}%</th>${costs.map(c=>{const v=portfolio({...state.settings,benefitFactor:b,costFactor:c}).npv;return `<td class="${v>=0?'positive':'negative'}">${short(v)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><p style="font-size:10px;margin:18px 0">Each cell replaces the benefit and cost multipliers while holding horizon, hurdle rate, delay, and capacity policy fixed. Green = positive NPV; peach = negative NPV.</p><h2>One assumption at a time</h2><div class="table-wrap"><table><thead><tr><th>DRIVER</th><th>LOWER CASE</th><th>CURRENT</th><th>HIGHER CASE</th></tr></thead><tbody>${[['Benefits', 'benefitFactor',80,120],['Costs','costFactor',80,120],['Hurdle rate','rate',Math.max(0,state.settings.rate-3),state.settings.rate+3],['Delay (months)','delay',Math.max(0,state.settings.delay-3),state.settings.delay+3]].map(([name,key,low,high])=>`<tr><td>${name}</td><td>${short(portfolio({...state.settings,[key]:low}).npv)}<small> (${low}${key==='delay'?' mo':'%'})</small></td><td>${short(a.npv)}</td><td>${short(portfolio({...state.settings,[key]:high}).npv)}<small> (${high}${key==='delay'?' mo':'%'})</small></td></tr>`).join('')}</tbody></table></div></div></div>`;}
function evidence(){return `<div class="insight" style="margin:0 0 22px"><b>▤</b><p><strong>Evidence before confidence.</strong> All five projects are examples. “Verified” describes the example's baseline quality, not a verification performed by this tool. Monetary figures remain forecasts; operational observations do not establish attributable cash savings.</p></div><div class="health-grid">${results().map(({p,r})=>`<article class="panel"><div class="panel-head"><div><h2><button class="name-button" data-project="${esc(p.id)}">${esc(p.name)} ↗</button></h2><p>${esc(p.owner)} · ${p.age} months since launch</p></div>${badge(r.health.action,r.health.action==='Healthy'?'green':r.health.action==='Escalate'?'red':'amber')}</div><div class="health-row"><span>${esc(p.kpi)}</span><b>${p.baseline==='Missing'?'Unmeasured':p.before+' '+esc(p.unit)} → ${p.after} ${esc(p.unit)}</b></div><div class="health-row"><span>Baseline quality</span>${badge(p.baseline,p.baseline==='Verified'?'green':'amber')}</div>${r.health.signals.map(s=>`<div class="health-row"><span>${s.name}</span>${badge(s.value,s.level===2?'red':s.level===1?'amber':'green')}</div>`).join('')}<div class="health-row"><span>Compute variance vs budget</span><b>${p.computeBudget?((p.compute/p.computeBudget-1)*100).toFixed(0)+'%':'No budget'}</b></div><p class="evidence">${esc(p.evidence)}</p><p class="evidence"><strong>Next decision: ${r.recommendation}.</strong> ${p.baseline!=='Verified'?'Reconstruct a comparable baseline and validate value attribution. ':''}${r.health.action!=='Healthy'?'Resolve flagged signals before expansion. ':'Validate sustained results and operating costs at the next monthly review. '}Reassess if NPV falls below zero or health deteriorates.</p></article>`).join('')}</div>`;}
function method(){return `<article class="panel method"><div class="eyebrow">MODEL TRANSPARENCY</div><h2>Built for a business case you can defend.</h2><p>The supplied “Measure and demonstrate AI business value” document informs the four-part value framework, stakeholder metrics, baseline evidence, and early warning indicators. Its learning exercises are reference content, not instructions to this application.</p><h3>Four parts of AI value</h3><ul><li><b>Direct savings:</b> expenses reduced or avoided. Do not also count the same labor as recovered capacity.</li><li><b>Indirect gains:</b> retention, quality, revenue, or reduced complaints. Only the explicitly cash-qualified share enters the financial case.</li><li><b>Productivity:</b> hours recovered × loaded hourly rate × realization. Reported separately; included only when the capacity option is enabled.</li><li><b>Full costs:</b> build, data preparation, training, inference compute, storage, maintenance, and human oversight. Include integration and governance spend in the relevant cost fields.</li></ul><h3>Monthly cash flow model</h3><p>Implementation, data preparation, and training are paid at month zero. Operating costs begin in month one, including during rollout delays. Benefits begin after the project delay plus scenario delay and ramp linearly to full production over the entered ramp months. Benefits are multiplied by adoption and the scenario benefit factor. Yearly benefit and cost growth apply at each twelve-month boundary.</p><h3>Capital budgeting conventions</h3><p><b>NPV:</b> − initial capital + Σ monthly net benefit ÷ (1 + annual discount rate)<sup>month/12</sup>. <b>IRR:</b> the monthly rate that makes NPV zero, annualized as (1 + monthly IRR)<sup>12</sup> − 1. N/A means no unique conventional IRR, no positive inflow, or no root within the search bounds. <b>Payback:</b> first monthly cumulative cash crossing, with linear interpolation. Discounted payback uses discounted monthly flows. Returns beyond the horizon are shown explicitly.</p><p><b>ROI (total cost basis):</b> (horizon benefits − horizon costs) ÷ horizon costs. <b>Capital ROI:</b> the same net benefit ÷ initial capital. Both are available in each project's cash-flow view. The reference's capital deployed convention includes first-year operating costs; the tool labels its initial capital basis separately.</p><h3>Reference payback is shown separately</h3><p>The reference uses (implementation + first-year operating costs) ÷ (annual direct savings + productivity − annual operating costs), excluding indirect gains. This simplified ratio is available in project detail. It ignores actual ramp and adoption and counts first-year operating costs in the numerator as well as the annual net benefit denominator. Our primary payback uses the monthly cash schedule. The reference also contains conflicting example payback summaries, so they are not copied as validated outputs.</p><h3>Health signals and decision rules</h3><p>Reference adoption alerts: below 40% after three months → monitor; below 20% after six months → red flag requiring a recovery plan review. Two yellow signals → investigate; two red → escalate. Application policy additionally investigates any single red. Pipeline thresholds (98% watch, below 95% red) are configurable product assumptions represented here as fixed demo policy. Accuracy is yellow when below its project target and flat or declining. Missing sponsor is red; limited engagement is yellow.</p><p>Intervene when evidence is incomplete or health requires investigation/escalation; otherwise rework when NPV ≤ 0, scale a production investment with ≥ 80% adoption and positive NPV, or continue. These deterministic recommendations support human judgment. They are not autonomous funding decisions.</p><h3>Scope and limitations</h3><p>USD, nominal, before-tax estimates. No depreciation tax shield, working capital, terminal value, financing, shared infrastructure savings, project dependencies, or budget optimization. Portfolio totals assume additive, independent benefits and costs; check overlap before approval. Data is saved only in this browser. There is no company login, shared database, or live telemetry connection. Export captures assumptions and monthly results for review.</p></article>`;}
function render(){const labels={overview:['Portfolio overview','Make every AI investment count.','A clear view of value, capital returns, and the signals behind them.'],scenarios:['Scenario lab','Test the case before you fund it.','Explore uncertainty and see what changes your investment decision.'],evidence:['Evidence & health','Look beyond the return.','Baselines, adoption, and the early signals that keep the value case honest.'],method:['Methodology','Transparent assumptions. Defensible decisions.','Understand the value framework and every calculation behind the portfolio.']};if(!labels[state.view])state.view='overview';const l=labels[state.view];$('#breadcrumb').textContent=l[0];$('#title').textContent=l[1];$('#subtitle').textContent=l[2];$('.nav.active')?.classList.remove('active');$(`[data-view="${state.view}"]`).classList.add('active');$('#years').value=state.settings.years;$('#rate').value=state.settings.rate;document.querySelectorAll('[data-scenario]').forEach(b=>b.classList.toggle('selected',b.dataset.scenario===state.scenario));$('#view').innerHTML=({overview,scenarios,evidence,method})[state.view]();bindView();save();if(selected&&!$("#detail").hidden){const p=state.projects.find(x=>x.id===selected);if(p){$("#detail-results").innerHTML=detailResults(p);$("#detail-cash").innerHTML=detailCash(p);}}}
function bindView(){document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>openDetail(b.dataset.project));document.querySelectorAll('[data-include]').forEach(b=>b.onchange=()=>{state.excluded=b.checked?state.excluded.filter(id=>id!==b.dataset.include):[...state.excluded,b.dataset.include];render();});$('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});document.querySelectorAll('[data-setting]').forEach(i=>i.oninput=e=>{const key=i.dataset.setting;state.settings[key]=+i.value;state.scenario='custom';const draft=document.createElement("div");draft.innerHTML=scenarios();$(".metrics").replaceWith(draft.querySelector(".metrics"));const output=$(".scenario-grid > .panel:last-child");output.replaceWith(draft.querySelector(".scenario-grid > .panel:last-child"));$("#"+key+"-value").textContent=i.value+(key==="delay"?" months":"%");document.querySelectorAll("[data-scenario]").forEach(b=>b.classList.remove("selected"));save();if(selected){const p=state.projects.find(x=>x.id===selected);$("#detail-results").innerHTML=detailResults(p);$("#detail-cash").innerHTML=detailCash(p);}});$('#capacity')?.addEventListener('change',e=>{state.settings.capacity=e.target.checked;render();});}
const specs=[['upfront','Implementation ($)',0,1e9],['data','Data preparation ($)',0,1e9],['training','Training & change ($)',0,1e9],['compute','Annual compute ($)',0,1e9],['storage','Annual storage ($)',0,1e9],['maintenance','Annual maintenance ($)',0,1e9],['oversight','Annual oversight ($)',0,1e9],['direct','Annual direct savings ($)',0,1e9],['indirect','Annual indirect gains ($)',0,1e9],['indirectCash','Indirect cash share (%)',0,100],['hours','Hours recovered / year',0,1e7],['hourly','Loaded cost / hour ($)',0,10000],['realization','Capacity realization (%)',0,100],['adoption','User adoption (%)',0,100],['ramp','Ramp to full benefit (mo)',1,60],['delay','Project delay (mo)',0,60],['growth','Annual benefit growth (%)',0,50],['costGrowth','Annual cost growth (%)',0,50],['before','Baseline metric',0,1e9],['after','Observed metric',0,1e9],['target','Business KPI target',0,1e9],['pipeline','Pipeline health (%)',0,100],['accuracy','Model accuracy (%)',0,100],['accuracyTarget','Accuracy target (%)',0,100],['trend','Accuracy trend (pp/mo)',-10,10],['computeBudget','Annual compute budget ($)',0,1e9],['age','Months since launch',0,120]];
function detailResults(p){const r=calculate(p,state.settings);return `<div class="detail-results"><div><small>NPV</small><strong>${short(r.npv)}</strong></div><div><small>IRR</small><strong>${pct(r.irr)}</strong></div><div><small>Payback</small><strong>${pb(r.payback)}</strong></div></div><p class="evidence">${recBadge(r.recommendation)} · ${r.health.action} · ${state.settings.capacity?'Includes capacity proxy':'Cash benefits only'}</p>`;}
function detailCash(p){const r=calculate(p,state.settings);return `<h3>Cash flow audit</h3><div class="table-wrap"><table><thead><tr><th>YEAR</th><th>BENEFITS</th><th>OP. COSTS</th><th>NET</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td>${short(r.cap)} setup</td><td>${short(-r.cap)}</td></tr>${r.yearly.map(y=>`<tr><td>${y.year}</td><td>${short(y.benefit)}</td><td>${short(y.cost)}</td><td>${short(y.net)}</td></tr>`).join('')}</tbody></table></div><p class="evidence">ROI (total costs): <b>${pct(r.roi)}</b> · Capital ROI (initial capital): <b>${r.cap?pct(r.capitalROI):'N/A'}</b><br>Discounted payback: <b>${pb(r.discountedPayback)}</b><br>Reference simplified payback: <b>${p.direct+r.capacity-operating(p)>0?pb(r.referencePayback):'Not reached'}</b><br>Recovered capacity proxy, before adoption: <b>${money(r.capacity)}/year</b></p>`;}
function openDetail(id){selected=id;const p=state.projects.find(x=>x.id===id);if(!p)return;$('#detail').hidden=false;$('#detail').innerHTML=`<div class="detail-head"><div><div class="eyebrow">LIVE BUSINESS CASE</div><h2>${esc(p.name)}</h2></div><button class="close" id="close-detail" aria-label="Close project">×</button></div><p class="description">${esc(p.description)}</p><div id="detail-results">${detailResults(p)}</div><p class="detail-note">Illustrative assumptions. Changes update all portfolio views immediately and save in this browser.</p><h3>Investment & full operating costs</h3><div class="fields">${specs.slice(0,7).map(fieldMarkup).join('')}</div><h3>Benefits & delivery assumptions</h3><div class="fields">${specs.slice(7,18).map(fieldMarkup).join('')}</div><h3>Evidence & leading indicators</h3><div class="fields"><label>KPI name<input data-text="kpi" value="${esc(p.kpi)}" maxlength="80"></label><label>Metric unit<input data-text="unit" value="${esc(p.unit)}" maxlength="20"></label>${specs.slice(18).map(fieldMarkup).join('')}<label>Baseline quality<select data-text="baseline">${['Verified','Partial','Missing'].map(v=>`<option ${p.baseline===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Sponsor engagement<select data-text="sponsor">${['Engaged','Limited','Missing'].map(v=>`<option ${p.sponsor===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Stage<select data-text="stage">${['Idea','Pilot','Production'].map(v=>`<option ${p.stage===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Executive owner<input data-text="owner" value="${esc(p.owner)}" maxlength="60"></label><label class="wide">Evidence, attribution & next steps<textarea data-text="evidence" rows="4" maxlength="2500">${esc(p.evidence)}</textarea></label></div><div id="detail-cash">${detailCash(p)}</div><div class="detail-actions"><button class="btn" id="duplicate">Duplicate case</button><button class="btn" id="remove">Remove automation</button></div>`;
function fieldMarkup([key,label,min,max]){return `<label>${label}<input data-field="${key}" type="number" min="${min}" max="${max}" step="${['before','after','target','pipeline','accuracy','accuracyTarget','trend','hourly'].includes(key)?'.1':'1'}" value="${p[key]}"></label>`;}
$('#close-detail').onclick=closeDetail;$('#detail').querySelectorAll('[data-field]').forEach(i=>i.oninput=()=>{if(i.value===''||!i.checkValidity())return;p[i.dataset.field]=+i.value;updateDetail(p);});$('#detail').querySelectorAll('[data-text]').forEach(i=>i.oninput=()=>{p[i.dataset.text]=i.value;updateDetail(p);});$('#duplicate').onclick=()=>{const copy=structuredClone(p);copy.id=crypto.randomUUID();copy.name+=' (comparison)';state.projects.push(copy);render();openDetail(copy.id);toast('Comparison case added');};$('#remove').onclick=()=>{if(!confirm(`Remove ${p.name} from this browser's portfolio?`))return;state.projects=state.projects.filter(x=>x.id!==id);state.excluded=state.excluded.filter(x=>x!==id);closeDetail();render();toast('Automation removed');};$('#close-detail').focus();}
function updateDetail(p){$('#detail-results').innerHTML=detailResults(p);$('#detail-cash').innerHTML=detailCash(p);render();}
function closeDetail(){$('#detail').hidden=true;const id=selected;selected=null;$(`[data-project="${id}"]`)?.focus();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render();});document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{state.scenario=b.dataset.scenario;Object.assign(state.settings,({base:{benefitFactor:100,costFactor:100,delay:0},downside:{benefitFactor:75,costFactor:120,delay:3},upside:{benefitFactor:120,costFactor:95,delay:0}})[state.scenario]);render();if(selected)openDetail(selected);});$('#years').onchange=e=>{state.settings.years=+e.target.value;render();if(selected)openDetail(selected);};$('#rate').oninput=e=>{if(e.target.value===''||!e.target.checkValidity())return;state.settings.rate=+e.target.value;render();if(selected){const p=state.projects.find(x=>x.id===selected);$('#detail-results').innerHTML=detailResults(p);$('#detail-cash').innerHTML=detailCash(p);}};$('#reset').onclick=()=>{if(!confirm('Reset all local changes and restore the five examples?'))return;state={projects:structuredClone(examples),settings:{...defaults},excluded:[],view:state.view,scenario:'base'};query='';closeDetail();render();toast('Example portfolio restored');};$('#add').onclick=()=>$('#add-dialog').showModal();$('#cancel-add').onclick=()=>$('#add-dialog').close();$('#add-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p={...structuredClone(examples[2]),id:crypto.randomUUID(),name:f.get('name').trim(),team:f.get('team').trim(),owner:f.get('owner').trim(),upfront:+f.get('upfront'),direct:+f.get('direct'),data:0,training:0,indirect:0,hours:0,adoption:70,stage:'Idea',baseline:'Missing',before:0,after:0,age:0,kpi:'Define business KPI',unit:'units',evidence:'New forecast. Establish a prelaunch baseline and validate all cost and benefit assumptions.',description:'New AI investment business case.'};if(!p.name||!p.team||!p.owner)return;state.projects.push(p);$('#add-dialog').close();e.target.reset();render();openDetail(p.id);toast('Automation added');};$('#export').onclick=()=>{const payload={exportedAt:new Date().toISOString(),currency:'USD',...state,results:results().map(({p,r})=>({id:p.id,...r})),portfolio:portfolio()};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='ai-capital-portfolio.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Assumptions and results exported');};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDetail();});render();


